package com.cpf.file.archive;import java.io.*;import java.nio.file.*;import java.util.*;import java.util.zip.*;
public final class CpfArchiveService {private final CpfArchiveProperties p;public CpfArchiveService(CpfArchiveProperties p){this.p=p;}
 public void zip(Path target,List<Path> files,Path base)throws IOException{p.validate();Files.createDirectories(target.toAbsolutePath().getParent());try(var out=new ZipOutputStream(Files.newOutputStream(target))){for(Path file:files){if(!Files.isRegularFile(file))throw new IllegalArgumentException("archive source must be a file");String name=base.relativize(file).toString().replace('\\','/');validateName(name);out.putNextEntry(new ZipEntry(name));Files.copy(file,out);out.closeEntry();}}}
 public List<Path> unzip(Path archive,Path target)throws IOException{p.validate();Files.createDirectories(target);long compressed=Math.max(1,Files.size(archive));long expanded=0;int entries=0;List<Path> result=new ArrayList<>();try(var in=new ZipInputStream(Files.newInputStream(archive))){ZipEntry e;byte[] buffer=new byte[65536];while((e=in.getNextEntry())!=null){if(++entries>p.getMaxEntries())throw new IOException("archive entry limit exceeded");validateName(e.getName());Path output=target.resolve(e.getName()).normalize();if(!output.startsWith(target.normalize()))throw new IOException("archive traversal blocked");if(e.isDirectory()){Files.createDirectories(output);continue;}Files.createDirectories(output.getParent());try(OutputStream out=Files.newOutputStream(output,StandardOpenOption.CREATE_NEW)){int n;while((n=in.read(buffer))>=0){expanded+=n;if(expanded>p.getMaxExpandedBytes()||expanded/(double)compressed>p.getMaxExpansionRatio())throw new IOException("archive expansion limit exceeded");out.write(buffer,0,n);}}result.add(output);}}return List.copyOf(result);}
 private static void validateName(String n)throws IOException{if(n==null||n.isBlank()||n.startsWith("/")||n.contains("..")||n.indexOf('\0')>=0)throw new IOException("unsafe archive entry");}}
